  const args = development
    ? ['--import', pathToFileURL(createRequire(import.meta.url).resolve('tsx')).href, server, root]
    : [server, root];
  return JSON.stringify({ mcpServers: { jev_files: { type: 'stdio', command: process.execPath, args } } });
