export function createClaudeAdapter(
  runner: ProcessRunner = runProcess,
): CodingAgentAdapter {
  return async ({ root, task, context }, options = {}) => {
    throwIfInterrupted(options.signal);
    const boundedTask = requireBoundedTask(task.trim());
    if (!boundedTask) throw new Error('Claude requires a non-empty repository task.');
    const prompt = buildClaudePrompt(boundedTask, context);
    if (prompt.length > MAX_WORKER_PROMPT_LENGTH) throw new Error('Claude prompt exceeds its size limit.');
    const startedAt = performance.now();
    const request = {
      command: 'claude',
      args: [
        '-p',
        '--model',
        CLAUDE_MODEL,
        '--effort',
        CLAUDE_EFFORT,
        '--output-format',
        'stream-json',
        '--verbose',
        '--permission-mode',
        'acceptEdits',
        '--permission-prompts',
        'none',
        '--max-turns',
        String(CLAUDE_MAX_TURNS),
        '--no-session-persistence',
        '--restricted',
        '--setting-sources',
        '',
        '--settings',
        JSON.stringify(CLAUDE_SESSION_SETTINGS),
        '--strict-mcp-config',
        '--disable-slash-commands',
        '--no-chrome',
        '--tools',
        'Read,Write,Edit,Glob,Grep',
        '--mcp-config',
        buildClaudeToolsConfig(root),
        '--allowedTools',
        'mcp__jev_files__rename_file',
        '--',
        prompt,
      ],
      cwd: root,
      timeoutMs: CLAUDE_TIMEOUT_MS,
    };
    const output = createWorkerOutput('claude');
    const result = await runner(request, { ...options, onStdout: output.write });
    validateProcessResult(result);
    const normalized = output.finish(result.stdout);

    return {
      agent: 'claude',
